#' Example National Address Database addresses
#'
#' @description
#' A small baked example fixture containing Hamilton County, Ohio rows from
#' revision 23 of the National Address Database. See `?nad` for more
#' information about the National Address Database.
#'
#' The fixture was derived once from the Hamilton County revision 23 source and
#' is not intended to be regenerated by package users. Use `nad()` when you
#' need complete county data.
#' @source U.S. Department of Transportation, National Address Database,
#'   revision 23. USDOT identifies the NAD as a federal government work
#'   available for reuse; see its
#'   [disclaimer](https://www.transportation.gov/mission/open/gis/national-address-database/national-address-database-nad-disclaimer).
#'   Packaged-data provenance and terms are recorded in
#'   `system.file("DATA-SOURCES", package = "addr")`.
#'
#' @param match_prepared logical; return the example data preprocessed with
#'   `addr_match_prepare()`?
#' @returns If `match_prepared = FALSE`, a tibble with 5,000 rows and 7
#'   columns. If `match_prepared = TRUE`, an `addr_match_index`.
#' @export
#' @examples
#' nad_example_data()
#' nad_example_data(match_prepared = TRUE)
nad_example_data <- function(match_prepared = FALSE) {
  stopifnot(
    "match_prepared must be TRUE or FALSE" = is.logical(match_prepared) &&
      length(match_prepared) == 1L &&
      !is.na(match_prepared)
  )

  if (match_prepared) {
    return(
      readRDS(
        system.file(
          "extdata",
          "nad_39061_mp.rds",
          package = "addr",
          mustWork = TRUE
        )
      )
    )
  }

  readRDS(
    system.file(
      "extdata",
      "nad_39061.rds",
      package = "addr",
      mustWork = TRUE
    )
  )
}

#' Example addresses
#'
#' `voter_addresses()` returns 2,000 unique formatted addresses from the
#' packaged National Address Database revision 23 fixture. The historical
#' function name is retained for compatibility; these examples are not drawn
#' from voter-registration records.
#'
#' Earlier versions used the Hamilton County voter export downloaded on
#' 2024-09-12 from
#' \samp{https://votehamiltoncountyohio.gov/download.php?file=VoterListExport-20240912-no.csv}.
#' That fixture was replaced because its redistribution terms were unconfirmed.
#' @source U.S. Department of Transportation, National Address Database,
#'   revision 23. USDOT identifies the NAD as a federal government work
#'   available for unrestricted reuse; see the
#'   [NAD disclaimer](https://www.transportation.gov/mission/open/gis/national-address-database/national-address-database-nad-disclaimer)
#'   and `system.file("DATA-SOURCES", package = "addr")`.
#' @returns a character vector
#' @export
#' @examples
#' voter_addresses() |>
#'   head()
voter_addresses <- function() {
  readRDS(
    system.file(
      "extdata",
      "voter_addresses.rds",
      package = "addr",
      mustWork = TRUE
    )
  )
}

#' Example line-one addresses
#'
#' Cincinnati Eviction Hotspots from the Eviction Lab's licensed download
#' archive, covering 2022-09-01 through 2023-08-31. These are historical
#' examples, not current building rankings or eviction estimates.
#' @source Eviction Lab, Princeton University, Eviction Tracking System,
#'   Cincinnati hotspot report in
#'   [hotspots_reports.zip](https://eviction-lab-data-downloads.s3.amazonaws.com/ets/hotspots_reports.zip).
#'   The [provider's download site](https://data-downloads.evictionlab.org/)
#'   distributes this database under the
#'   [Open Data Commons Attribution License (ODC-BY 1.0)](https://opendatacommons.org/licenses/by/1-0/).
#'   Attribution and redistribution terms are included in
#'   `system.file("DATA-SOURCES", package = "addr")` and
#'   `system.file("ODC-BY-1.0", package = "addr")`.
#' @returns a tibble with 100 rows and 9 columns
#' @export
#' @examples
#' elh_data()
elh_data <- function() {
  readRDS(
    system.file(
      "extdata",
      "elh_data.rds",
      package = "addr",
      mustWork = TRUE
    )
  )
}
